package com.smartgrocery.entity; import jakarta.persistence.*; import java.math.BigDecimal; import java.time.Instant; @Entity @Table(name="orders") public class StoreOrder { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; private String customerName; private String status="PLACED"; private BigDecimal total=BigDecimal.ZERO; private Instant createdAt=Instant.now(); public StoreOrder(){} public StoreOrder(String n,BigDecimal t){customerName=n;total=t;} public Long getId(){return id;} public String getCustomerName(){return customerName;} public String getStatus(){return status;} public BigDecimal getTotal(){return total;} public Instant getCreatedAt(){return createdAt;} public void setStatus(String s){status=s;} }